-- Create "notify_broadcasts" table
CREATE TABLE `notify_broadcasts` (`id` bigint unsigned NOT NULL AUTO_INCREMENT, `created_at` datetime(3) NOT NULL, `updated_at` datetime(3) NOT NULL, `title` varchar(200) NOT NULL, `content` longtext NOT NULL, `channels` json NOT NULL, `target_type` enum('all','active','specified') NOT NULL DEFAULT "all", `target_ids` json NULL, `scheduled_at` datetime(3) NULL, `status` enum('pending','sending','done','canceled') NOT NULL DEFAULT "pending", `created_by` bigint unsigned NOT NULL, `audience` bigint NOT NULL DEFAULT 0, `sent_count` bigint NOT NULL DEFAULT 0, `failed_count` bigint NOT NULL DEFAULT 0, `started_at` datetime(3) NULL, `finished_at` datetime(3) NULL, PRIMARY KEY (`id`), INDEX `notifybroadcast_status_scheduled_at` (`status`, `scheduled_at`)) CHARSET utf8mb4 COLLATE utf8mb4_bin;
